values
('38b802d2-7f26-4c88-a105-5df28473df1f', 'Apartamento de 3 habitaciones en Prebo, piso 5', 'Ubicado en el edificio Prebo I, con 105 m² distribuidos en sala-comedor, cocina con desayunador, tres habitaciones (la principal con baño privado) y cuarto de servicio con área de lavado. El edificio tiene vigilancia 24 horas, ascensor y planta eléctrica. Se entrega con cocina empotrada y clósets en todas las habitaciones. Documentos al día.', 1, 1, 'Carabobo', 'Valencia', 'carabobo', 'Valencia', 'Prebo', 10.1901994, -68.0137349, 98000, 'USD', 105, 105, 3, 2, 2, 5, 'Bueno', 18, '/propiedades/prop-01-1.jpg', true, 73, '2026-07-09 23:00:00+00', '2026-07-09 23:00:00+00'),
('38b802d2-7f26-4c88-a105-5df28473df1f', 'Apartamento a estrenar en La Trigaleña, 98 m²', 'Obra nueva en residencias Agua Viva, tercera etapa. 98 m² con sala-comedor amplia, cocina equipada, tres habitaciones y dos baños completos. Balcón con vista a la zona norte, piso 7. El conjunto cuenta con gimnasio, salón de fiestas, vigilancia y planta eléctrica para áreas comunes. Listo para habitar, con financiamiento directo del constructor.', 1, 1, 'Carabobo', 'Valencia', 'carabobo', 'Valencia', 'La Trigaleña', 10.1910289, -68.0029256, 128000, 'USD', 98, 98, 3, 2, 2, 7, 'A estrenar', 0, '/propiedades/prop-02-1.jpg', true, 684, '2026-07-12 04:00:00+00', '2026-07-12 04:00:00+00'),
('38b802d2-7f26-4c88-a105-5df28473df1f', 'Apartamento 2 habitaciones en Trigal Norte, 72 m²', 'Apartamento en piso 3 de un edificio de 8, con 72 m² y buena iluminación natural. Sala-comedor, cocina semiabierta, dos habitaciones con clósets y un baño. Un puesto de estacionamiento y área de lavado en la azotea. Zona residencial tranquila, a pocos minutos del CC Trigal Norte.', 1, 1, 'Carabobo', 'Valencia', 'carabobo', 'Valencia', 'Trigal Norte', 10.1859882, -68.0177071, 58000, 'USD', 72, 72, 2, 1, 1, 3, 'Bueno', 12, '/propiedades/prop-03-1.jpg', false, 709, '2026-09-06 08:00:00+00', '2026-09-06 08:00:00+00'),
('38b802d2-7f26-4c88-a105-5df28473df1f', 'Se vende apartamento en El Parral, 68 m²', 'Piso 2 de 5, sin ascensor. Consta de sala-comedor, cocina, dos habitaciones y un baño. Incluye un puesto de estacionamiento descubierto y maletero. El edificio se encuentra en mantenimiento activo y las cuotas de condominio están al día. Ideal para primera vivienda o inversión en alquiler.', 1, 1, 'Carabobo', 'Valencia', 'carabobo', 'Valencia', 'El Parral', 10.1784516, -68.0098349, 42000, 'USD', 68, 68, 2, 1, 1, 2, 'Bueno', 25, '/propiedades/prop-04-1.jpg', false, 724, '2026-09-22 08:00:00+00', '2026-09-22 08:00:00+00'),
